  /** A task's delivery posture, for the emit_card land-gate (G-1 + L2). */
  taskDelivery(taskId: string): "direct-pr" | "local-only" | undefined {
    const record = this.options.tasks.get(taskId);
    if (!record) return undefined;
    if (!record.repoId) return "local-only";
    return this.options.repos.get(record.repoId)?.delivery;
  }

  private applyEvent(task: TaskRuntime, event: FmEvent): void {
    switch (event.type) {
      case "assistant_delta": {
        task.currentTurnText += event.text;
        const card = this.cards.get(task.cardId);
        if (card) {
          this.cards.set(task.cardId, { ...card, body: task.currentTurnText });
          this.scheduleCardBroadcast();
        }
        break;
      }
      case "turn_failed": {
        // Held on the runtime until the prompt resolves; turnComplete turns
        // it into the failure report instead of "(no report)".
        task.lastTurnError = event.error;
        break;
      }
      case "turn_end": {
        if (task.currentTurnText.trim()) {
          task.lastCompleteText = task.currentTurnText;
          task.turnReport = task.currentTurnText;
        }
        task.currentTurnText = "";
        const snapshot = this.cards.get(task.cardId);
        if (snapshot) this.options.cardStore.upsert(snapshot);
        if (event.usage) {
          const model = task.transport?.modelRef();
          this.options.recordUsage?.({
            taskId: task.id,
            ...(task.accountId ? { accountId: task.accountId } : {}),
            ...(model ? { model } : {}),
            usage: event.usage,
          });
        }
        break;
      }
      default:
        break;
    }
  }

  /** A card emitted by a crewmate through its emit_card tool (D-9, Q3). */
  private addCrewmateCard(task: TaskRuntime, input: EmittedCardInput): string {
    return this.upsertEmittedCard(input, {
      taskId: task.id,
      meta: `${task.crewmate} · fm/task-${task.id}`,
      mintId: () => {
        this.cardSeq += 1;
        return `card-${task.id}-${this.cardSeq}`;
      },
      // Idempotent, like resolveFirstmateCardId: emit_card hands the model
      // back the resolved id, so a crewmate revising its own card resends
      // that id. Prefixing it again would mint a duplicate instead.
      resolveId: (stableId) =>
        stableId.startsWith(`card-${task.id}-`) ? stableId : `card-${task.id}-${stableId}`,
    });
  }

  /**
   * A card emitted by the Firstmate agent - its only user-facing output
   * channel (report section 4a). Decision answers route back to the agent
   * as [fm-op] messages through act().
   */
  addFirstmateCard(input: EmittedCardInput): string {
    return this.upsertEmittedCard(input, {
      ...(input.taskId ? { taskId: input.taskId } : {}),
      meta: "firstmate",
      mintId: () => {
        this.cardSeq += 1;
        return `${FIRSTMATE_CARD_PREFIX}${this.cardSeq}-${randomUUID().slice(0, 6)}`;
      },
      resolveId: resolveFirstmateCardId,
    });
  }

