  /** Auth-vs-generic dispatch for every failure channel (create, throw, provider). */
  private raiseSessionFailureCard(message: string): void {
    if (isAuthFailureMessage(message) || message.includes("No signed-in model")) {
      this.options.supervisor.addAuthDecisionCard(
        AUTH_CARD_ID,
        "firstmate",
        `Firstmate needs a signed-in model to answer.\n\n${formatFlagshipError(this.session?.modelRef(), message)}`,
      );
      return;
    }
    this.raiseTurnFailureCard(formatFlagshipError(this.session?.modelRef(), message));
  }

  private raiseTurnFailureCard(message: string): void {
    // Stable id: repeated failures (a provider outage across several turns)
    // revise one card in place instead of stacking copies.
    const body = this.runawayRefused
      ? `${message}\n\nFirstmate will not start another turn until you Retry.`
      : message;
    this.options.supervisor.addFirstmateCard({
      id: "turn-failure",
      kind: "decision",
      title: "Firstmate hit an error",
      body,
      actions: [{ id: "retry-firstmate", label: "Retry" }],
    });
  }

  /**
   * Last-resort safety net for a pinned reasoning flagship: after repeated
   * max_time_limit / token-generation failures, refuse the next idle turn
   * instead of hanging again. Retry (or a clean turn) clears it. Never
   * changes the captain's chosen default flagship.
   */
  private noteRunaway(error: string): void {
    if (!isRunawayProviderError(error)) {
      this.runawayStreak = 0;
      return;
    }
    this.runawayStreak += 1;
    if (this.runawayStreak >= RUNAWAY_REFUSE_AFTER) {
      this.runawayRefused = true;
    }
  }

  /** Start one answer-ownership scope for the newly originating question. */
  private beginAnswerScope(): void {
    this.turnAnswerOwner = undefined;
    this.turnCrewAlreadyReported = false;
    this.turnCrewOwnedTasks = new Set();
    this.turnCrewShowedDecision = false;
  }

  /**
   * The one card a reporting crewmate's ownership must not swallow: the
   * captain's control surface for that task, such as the merge-pr decision
   * the PR-CI rule asks for. A decision naming an owned task is an action,
   * not a restatement of the crew's answer - but only while the crew has
   * shown no decision of its own, since a second one would be the very
   * duplicate this scope exists to prevent.
   */
  private isMissingControlSurface(card: EmittedCard): boolean {
    return (
      this.turnCrewAlreadyReported &&
      !this.turnCrewShowedDecision &&
      card.kind === "decision" &&
      card.taskId !== undefined &&
      this.turnCrewOwnedTasks.has(card.taskId)
    );
  }

  /**
   * Carry a crewmate's answer ownership onto its own report turn. A crew
   * wake refs its task; if that task already has a card on screen, the crew
   * has answered the captain and Firstmate must not card the same thing
   * again. Nothing on screen means nothing to repeat, so the turn stays
   * unowned and Firstmate can still answer for a silent or failed task.
   */
  private carryCrewAnswerOwnership(rows: InboxRow[]): void {
    // A batch that mixes in an unrefd wake may carry an unrelated thing the
    // captain still needs carded, so only a wholly crew-referring batch
    // claims the scope.
    if (rows.length === 0 || rows.some((row) => !row.ref)) return;
    const refs = new Set(rows.map((row) => row.ref).filter((ref): ref is string => Boolean(ref)));
    // A Firstmate card ABOUT a task (an answer with task_id, P1) is not the
    // crew's answer - only a card the crewmate itself emitted claims the scope.
    const shown = this.options.supervisor
      .cardsSnapshot()
      .filter(
        (card) =>
          card.taskId !== undefined &&
          refs.has(card.taskId) &&
          !card.id.startsWith(FIRSTMATE_CARD_PREFIX),
      );
    if (shown.length === 0) return;
    this.turnAnswerOwner = "crewmate";
    this.turnCrewAlreadyReported = true;
    this.turnCrewOwnedTasks = new Set(
      shown.map((card) => card.taskId).filter((taskId): taskId is string => Boolean(taskId)),
    );
    this.turnCrewShowedDecision = shown.some((card) => card.kind === "decision");
  }

  /** Stamp origin from the wake; reset the at-capacity refusal counter. */
  private beginMemoryTurn(origin: MemoryOrigin, canCreate: boolean): void {
    this.turnOrigin = origin;
    this.turnCanCreate = canCreate;
    this.memoryCapacityFails = 0;
  }
}

