    const card = this.cards.get(cardId);
    if (!card) return {};
    // Resolution records the captain's CHOICE, not operation success. All
    // actions retire their card before any external work can start.
    this.cards.delete(cardId);
    this.options.cardStore.resolve(cardId, actionId);
    this.recordCardResolution(card, actionId);
