        card.taskId,
        actionId === "discard-anyway" ? "discard" : actionId,
        actionId === "discard-anyway",
      );
      return {};
    }
    const chosen = card.actions.find((action) => action.id === actionId);
    if (actionId === "keep" && card.taskId) {
      // Host-owned settle: the card is gone; the crewmate stays idle.
      // Keep is not Later and does not decommission.
      return {};
