   * behavior never silently changes - highest-runway medium-or-better
   * catalog model Pi can serve, else the first available model.
   */
  private resolveModel(): { provider: string; id: string } | undefined {
    const chosen = this.options.settings.getFirstmateModel();
    // Leftover Anthropic sessions stay on disk; they are not offered until
    // API-key support lands, so pick a new default rather than crashing.
    if (chosen && chosen.provider !== "anthropic") return chosen;
    const available = this.options
      .availableModels()
      .filter((model) => model.provider !== "anthropic");
    if (available.length === 0) return undefined;
    const availableKeys = new Set(available.map((m) => `${m.provider}/${m.id}`));
    const catalog = this.options.quotaModels()?.models ?? [];
    // Medium before high, runway order within each slot. Premium never
    // appears here: it is not an automatic slot (captain decision A).
    for (const bucket of ["medium", "high"] as const) {
      for (const model of catalog) {
        const piProvider = QUOTA_TO_PI_PROVIDER[model.provider];
        if (!piProvider) continue;
        if (!availableKeys.has(`${piProvider}/${model.id}`)) continue;
        if (this.slotOf({ provider: piProvider, id: model.id }) !== bucket) continue;
        const derived = { provider: piProvider, id: model.id };
        this.options.settings.setFirstmateModel(derived);
        return derived;
      }
    }
    const fallback = available.find((model) => !this.isPremium(model));
    if (!fallback) return undefined;
    this.options.settings.setFirstmateModel(fallback);
    return fallback;
  }

  private buildTools(): ToolDefinition[] {
    const supervisor = this.options.supervisor;
    const delegate: CrewDelegate = {
      commission: async (input) => {
        if (this.turnAnswerOwner === "firstmate") {
          throw new Error(
            "Answer ownership conflict: Firstmate already emitted a card for this question, so do not also spawn a crewmate for it.",
          );
        }
        const handle = await supervisor.commission(input);
        // Failed commissions do not claim the scope; successful immediate and
        // queued delegations do. The task's own emit_card surface is untouched.
        this.turnAnswerOwner = "crewmate";
        // Attach first (P1): the ask that caused the spawn is about the new task.
        this.asks.attach(handle.taskId, "spawn_crewmate");
        return handle;
      },
      // The ask is about the task the captain named, whatever the tool then
      // says about it - a refused settle is still about that task.
      steerCrewmate: (taskId, message) => {
        this.asks.attach(taskId, "steer_crewmate");
        return supervisor.steerCrewmate(taskId, message);
      },
      interruptCrewmate: (taskId, mode) => {
        this.asks.attach(taskId, "interrupt_crewmate");
        return supervisor.interruptCrewmate(taskId, mode);
      },
